import uuid
from django.conf import settings
from django.db import models
class Exercise(models.Model):
    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False); external_id = models.CharField(max_length=100, blank=True, null=True, unique=True); name = models.CharField(max_length=180); name_es = models.CharField(max_length=180, blank=True); slug = models.SlugField(max_length=200); category = models.CharField(max_length=80, blank=True); primary_muscles = models.JSONField(default=list); secondary_muscles = models.JSONField(default=list); equipment = models.CharField(max_length=100, blank=True); difficulty = models.CharField(max_length=40, blank=True); instructions = models.JSONField(default=list); instructions_es = models.JSONField(default=list, blank=True); force = models.CharField(max_length=20, blank=True); mechanic = models.CharField(max_length=20, blank=True); image_1 = models.URLField(blank=True); image_2 = models.URLField(blank=True); photo = models.BinaryField(null=True, blank=True, editable=False); photo_type = models.CharField(max_length=20, blank=True); source = models.CharField(max_length=120, default="Dynamo"); source_url = models.URLField(blank=True); is_custom = models.BooleanField(default=False); created_by = models.ForeignKey(settings.AUTH_USER_MODEL, null=True, blank=True, on_delete=models.CASCADE); active = models.BooleanField(default=True); created_at = models.DateTimeField(auto_now_add=True); updated_at = models.DateTimeField(auto_now=True)
    class Meta: indexes = [models.Index(fields=["name"]), models.Index(fields=["category", "equipment"])]
